   222	/// Inertia after a drag release. Friction decays velocity each tick; hitting a
   223	/// screen edge reflects velocity at 50% to feel bouncy without escaping.
   224	export async function applyThrow(
   225	  vx: number,
   226	  vy: number,
   227	  bounds: Rect,
   228	  pet: Pet | null,
   229	  stop: () => boolean,
   230	): Promise<void> {
   231	  throwing = true;
   232	  let pos = await currentLogicalPos();
   233	  if (!pos) { throwing = false; return; }
   234	
   235	  while (!stop() && throwing) {
   236	    if (Math.hypot(vx, vy) < PHYSICS_MIN_SPEED) break;
   237	
   238	    vx *= PHYSICS_FRICTION;
   239	    vy *= PHYSICS_FRICTION;
   240	
   241	    let nx: number = pos.x + vx * DT_SEC;
   242	    let ny: number = pos.y + vy * DT_SEC;
   243	    [vx, nx] = bounceX(vx, nx, bounds);
   244	    [vy, ny] = bounceY(vy, ny, bounds);
   245	
   246	    pos = { x: nx, y: ny };
   247	    try { await setLogical(pos); }
   248	    catch (e) { void invoke("log_debug", { msg: `roam: throw error: ${e}` }).catch(() => {}); break; }
   249	
   250	    pet?.setRow(vx > 0 ? 1 : 2);
   251	    await sleep(TICK_MS);
   252	  }
   253	
   254	  throwing = false;
   255	  pet?.clearRow();
   256	}
