   193	interface Sample { t: number; x: number; y: number }
   194	const samples: Sample[] = [];
   195	
   196	export function recordSample(pos: Point): void {
   197	  const now = performance.now();
   198	  samples.push({ t: now, x: pos.x, y: pos.y });
   199	  while (samples.length && now - samples[0].t > SAMPLE_WINDOW_MS) samples.shift();
   200	}
   201	
   202	export function releaseVelocity(): { vx: number; vy: number } | null {
   203	  if (samples.length < 2) return null;
   204	  const first = samples[0];
   205	  const last = samples[samples.length - 1];
   206	  const dt = last.t - first.t;
   207	  if (dt < 20) return null;
   208	  return {
   209	    vx: ((last.x - first.x) / dt) * 1000,
   210	    vy: ((last.y - first.y) / dt) * 1000,
   211	  };
   212	}
   213	
   214	export function clearSamples(): void {
   215	  samples.length = 0;
   216	}
