   258	/// Gravity fall after drag release (Shimeji-style). Pet accelerates downward
   259	/// until it lands on a surface (work area bottom or a window top edge).
   260	export async function applyFall(
   261	  vx: number,
   262	  bounds: Rect,
   263	  surfaces: Rect[],
   264	  pet: Pet | null,
   265	  stop: () => boolean,
   266	): Promise<void> {
   267	  throwing = true;
   268	  let pos = await currentLogicalPos();
   269	  if (!pos) { throwing = false; return; }
   270	
   271	  let vy = 0;
   272	  while (!stop() && throwing) {
   273	    vy += PHYSICS_GRAVITY * DT_SEC;
   274	    const nx: number = pos.x + vx * DT_SEC;
   275	    let ny: number = pos.y + vy * DT_SEC;
   276	
   277	    const floorY = findFloor(pos.x, nx, bounds, surfaces);
   278	    if (ny >= floorY) {
   279	      ny = floorY;
   280	      throwing = false;
   281	    }
   282	
   283	    pos = { x: Math.max(bounds.left, Math.min(bounds.right - WIN_W, nx)), y: ny };
   284	    try { await setLogical(pos); }
   285	    catch (e) { void invoke("log_debug", { msg: `roam: fall error: ${e}` }).catch(() => {}); break; }
   286	
   287	    pet?.setRow(vx > 0 ? 1 : 2);
   288	    await sleep(TICK_MS);
   289	  }
   290	
   291	  throwing = false;
   292	  pet?.clearRow();
   293	}
