   295	function bounceX(vx: number, nx: number, bounds: Rect): [number, number] {
   296	  if (nx < bounds.left || nx > bounds.right - WIN_W) {
   297	    return [-vx * 0.5, Math.max(bounds.left, Math.min(bounds.right - WIN_W, nx))];
   298	  }
   299	  return [vx, nx];
   300	}
   301	
   302	function bounceY(vy: number, ny: number, bounds: Rect): [number, number] {
   303	  if (ny < bounds.top || ny > bounds.bottom - WIN_H) {
   304	    return [-vy * 0.5, Math.max(bounds.top, Math.min(bounds.bottom - WIN_H, ny))];
   305	  }
   306	  return [vy, ny];
   307	}
   308	
   309	/// Find the highest surface (window top edge or work-area bottom) under the
   310	/// pet's horizontal range [x1, x2], returned as the pet's TOP-Y when resting on
   311	/// it. `pos.y` is the window's top-left, so landing = top at `surface.top - WIN_H`.
   312	function findFloor(x1: number, x2: number, bounds: Rect, surfaces: Rect[]): number {
   313	  let floor = bounds.bottom - WIN_H;
   314	  for (const s of surfaces) {
   315	    if (x2 < s.left || x1 > s.right) continue;
   316	    const top = s.top - WIN_H;
   317	    if (top < floor && top >= bounds.top) floor = top;
   318	  }
   319	  return floor;
   320	}
