   try {
     data = ctx.getImageData(0, 0, w, h).data;
   } catch {
     return []; // tainted (no CORS) , caller falls back to the fixed grid
   }
   const rowHas = new Uint8Array(h);
   for (let y = 0; y < h; y++) {
     const off = y * w * 4;
     for (let x = 0; x < w; x++) {
       if (data[off + x * 4 + 3] > ALPHA_THRESHOLD) { rowHas[y] = 1; break; }
     }
